// The mascot: the brand's own chick (the 4A line chick of the logo, app icon and menu-bar glyph) in colour — a warm
// yellow body under the icon's line — for moments: done, hatching, listening, thinking, onboarding. One chick: the
// drawing is the mark's geometry (Icons/MascotGeometry.swift, generated by assets/brand/chick.swift), posed and moved
// in code (Icons/MascotArt.swift), so it is crisp at any size and in both appearances.
//
//   let v = MascotView(clip: .peck, size: 44, backdrop: .dark); v.play(.peck) { … }   AppKit
//   let l = MascotLayer(); l.backdrop = .dark; l.play(.wobble)                        layer-built UIs (the island's ears)
//   MascotImage(clip: .idle, size: 64, backdrop: .light)                             SwiftUI
//
// `backdrop`: what the chick sits on — the island is always dark, the onboarding field reads as light; `.auto` follows
// the view's appearance. On dark the free marks (sound arcs, thought dots) turn light, the ground shadow goes, and the
// chick and egg get a thin white rim so their black line still reads on black.
//
// One shared 60 fps timer drives every playing layer and stops when none plays. Each tick renders the clip's pose at
// that moment into the layer's model `contents` (no CAAnimation), so offscreen renders (FrameCapture, `mascotframes`)
// see the same frame the screen does. Reduce Motion: the clip's still moment, no movement; a one-shot's completion
// still runs. The line glyphs (BlurtIcon.chicken, the menu-bar chick .blurt) move with GlyphMotion below.
import AppKit
import BlurtCore
import SwiftUI
import UserNotifications

enum MascotClip: String, CaseIterable {
    case idle, listening, thinking, wobble, hatching, happy, peck
}

/// What the mascot sits on (its free marks and shadow follow it).
enum MascotBackdrop {
    case auto, light, dark
}

/// The clips' timing and pictures of them (notifications, docs, tests).
final class MascotLibrary {
    static let shared = MascotLibrary()

    struct Clip {
        let duration: Double
        let loop: Bool
        /// the moment shown with Reduce Motion (and in pictures of the clip)
        let still: Double
    }

    func clip(_ c: MascotClip) -> Clip? {
        let t = MascotArt.timing(c)
        return Clip(duration: t.duration, loop: t.loop, still: t.still)
    }

    /// One moment of a clip as an image, `points` square at `scale` (`time` nil = the still moment). `backdrop` fills
    /// behind it (nil = transparent); `sticker`: the logo's white edge round the art, for any backdrop.
    func image(_ c: MascotClip, at time: Double? = nil, points: CGFloat, scale: CGFloat = 2, dark: Bool = false,
               backdrop: CGColor? = nil, sticker: Bool = false) -> CGImage? {
        let px = Int((points * scale).rounded())
        guard px > 0, let ctx = CGContext(data: nil, width: px, height: px, bitsPerComponent: 8, bytesPerRow: 0,
                                          space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                          bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        let r = CGRect(x: 0, y: 0, width: px, height: px)
        if let b = backdrop { ctx.setFillColor(b); ctx.fill(r) }
        var style = MascotStyle.forSize(points, dark: dark, scale: scale)
        style.sticker = sticker
        MascotArt.draw(ctx, in: r, pose: MascotArt.pose(c, at: time ?? MascotArt.timing(c).still), style: style)
        return ctx.makeImage()
    }

    /// The clip's still moment as a notification attachment, on the logo's sticker edge so it reads on the light and
    /// the dark notification (the system moves the file away, so a fresh copy each time).
    func attachment(_ c: MascotClip) -> [UNNotificationAttachment] {
        guard let img = image(c, points: 80, sticker: true) else { return [] }
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("blurt-mascot-\(c.rawValue)-\(UUID().uuidString).png")
        guard let png = NSBitmapImageRep(cgImage: img).representation(using: .png, properties: [:]), (try? png.write(to: url)) != nil,
              let a = try? UNNotificationAttachment(identifier: "mascot", url: url) else { return [] }
        return [a]
    }

    /// The clip sampled at `fps`, in order (docs / tests turn them into GIFs and contact sheets).
    func timelineFrames(_ c: MascotClip, points: CGFloat = 80, scale: CGFloat = 2, fps: Double = 12, dark: Bool = false,
                        backdrop: CGColor? = nil) -> [CGImage] {
        let t = MascotArt.timing(c)
        let n = max(1, Int((t.duration * fps).rounded()))
        return (0..<n + (t.loop ? 0 : 1)).compactMap {
            image(c, at: Double($0) / fps, points: points, scale: scale, dark: dark, backdrop: backdrop)
        }
    }
}

/// A layer that plays one clip at a time, drawn afresh for each moment at its size and scale.
final class MascotLayer: CALayer {
    private(set) var clip: MascotClip?
    private var started: CFTimeInterval = 0
    private var shown: Double = 0          // the clip time on screen
    private var done: (() -> Void)?
    /// What it sits on (`.auto` = the app's appearance; MascotView passes its own).
    var backdrop: MascotBackdrop = .auto { didSet { if oldValue != backdrop { redraw() } } }
    /// Set by MascotView from its effective appearance, for `.auto`.
    var appearsDark: Bool? { didSet { if oldValue != appearsDark { redraw() } } }
    var isPlaying: Bool { MascotDriver.shared.has(self) }

    override init() {
        super.init()
        contentsGravity = .resizeAspect
        contentsScale = 2
        actions = ["contents": NSNull(), "bounds": NSNull(), "position": NSNull()]
    }
    override init(layer: Any) { super.init(layer: layer) }
    required init?(coder: NSCoder) { fatalError() }

    private var dark: Bool {
        switch backdrop {
        case .light: return false
        case .dark: return true
        case .auto: return appearsDark ?? isDarkMode
        }
    }

    /// Plays `c` from its start (a loop runs until stop / another play). `completion` after a one-shot's end.
    func play(_ c: MascotClip, completion: (() -> Void)? = nil) {
        clip = c
        done = completion
        let t = MascotArt.timing(c)
        if reduceMotion {
            shown = t.still
            redraw()
            MascotDriver.shared.remove(self)
            if let d = done { done = nil; DispatchQueue.main.async(execute: d) }
            return
        }
        started = CACurrentMediaTime()
        shown = 0
        redraw()
        MascotDriver.shared.add(self)
    }

    /// Shows one moment of a clip, still: `frame` counts twelfths of a second from its start (0 = how it begins), nil =
    /// the clip's still moment.
    func show(_ c: MascotClip, frame: Int? = nil) {
        clip = c
        MascotDriver.shared.remove(self)
        shown = frame.map { Double(max(0, $0)) / 12 } ?? MascotArt.timing(c).still
        redraw()
    }

    func stop() { MascotDriver.shared.remove(self); done = nil }

    fileprivate func step(_ now: CFTimeInterval) -> Bool {
        guard let c = clip else { return false }
        let t = MascotArt.timing(c)
        shown = now - started
        if !t.loop && shown >= t.duration {
            shown = t.duration
            redraw()
            if let d = done { done = nil; d() }
            return false
        }
        redraw()
        return true
    }

    override func layoutSublayers() {
        super.layoutSublayers()
        redraw()
    }

    /// Draws the current moment at the layer's pixel size.
    private func redraw() {
        guard let c = clip, bounds.width >= 1 else { return }
        let side = min(bounds.width, bounds.height)
        let img = MascotLibrary.shared.image(c, at: shown, points: side, scale: max(1, contentsScale), dark: dark)
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        contents = img
        CATransaction.commit()
    }
}

/// One timer for every playing mascot, only while one plays.
private final class MascotDriver {
    static let shared = MascotDriver()
    private var layers = NSHashTable<MascotLayer>.weakObjects()
    private var timer: Timer?

    func has(_ l: MascotLayer) -> Bool { layers.contains(l) }
    func add(_ l: MascotLayer) {
        layers.add(l)
        guard timer == nil else { return }
        let t = Timer(timeInterval: 1.0 / 60, repeats: true) { [weak self] _ in self?.fire() }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }
    func remove(_ l: MascotLayer) {
        layers.remove(l)
        if layers.count == 0 { timer?.invalidate(); timer = nil }
    }
    private func fire() {
        let now = CACurrentMediaTime()
        for l in layers.allObjects where !l.step(now) { layers.remove(l) }
        if layers.count == 0 { timer?.invalidate(); timer = nil }
    }
}

/// AppKit host for a MascotLayer (decoration: hidden from VoiceOver unless given a label).
final class MascotView: NSView {
    let mascot = MascotLayer()

    init(clip: MascotClip? = nil, size: CGFloat, backdrop: MascotBackdrop = .auto) {
        super.init(frame: NSRect(x: 0, y: 0, width: size, height: size))
        wantsLayer = true
        mascot.backdrop = backdrop
        layer?.addSublayer(mascot)
        mascot.frame = bounds
        if let c = clip { show(c) }
        setAccessibilityElement(false)
    }
    required init?(coder: NSCoder) { fatalError() }

    override var intrinsicContentSize: NSSize { frame.size }
    override func layout() {
        super.layout()
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        mascot.frame = bounds
        mascot.contentsScale = window?.backingScaleFactor ?? 2
        CATransaction.commit()
    }
    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        mascot.appearsDark = effectiveAppearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
    }

    func play(_ c: MascotClip, completion: (() -> Void)? = nil) { mascot.play(c, completion: completion) }
    func show(_ c: MascotClip, frame: Int? = nil) { mascot.show(c, frame: frame) }
    func stop() { mascot.stop() }
    override func viewDidMoveToWindow() {
        if window == nil { mascot.stop() } else { viewDidChangeEffectiveAppearance() }
    }
}

/// SwiftUI: plays `clip` (a one-shot then rests on its last moment, or goes on with `then`); a new `clip` plays again.
struct MascotImage: NSViewRepresentable {
    var clip: MascotClip
    var then: MascotClip?
    var size: CGFloat
    var backdrop: MascotBackdrop = .auto

    final class Coordinator { var requested: MascotClip? }
    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeNSView(context: Context) -> MascotView {
        let v = MascotView(size: size, backdrop: backdrop)
        v.setContentHuggingPriority(.required, for: .horizontal)
        v.setContentHuggingPriority(.required, for: .vertical)
        return v
    }
    func updateNSView(_ v: MascotView, context: Context) {
        v.mascot.backdrop = backdrop
        guard context.coordinator.requested != clip else { return }
        context.coordinator.requested = clip
        let next = then
        v.play(clip) { [weak v] in if let n = next { v?.play(n) } }
    }
    func sizeThatFits(_ proposal: ProposedViewSize, nsView: MascotView, context: Context) -> CGSize? { CGSize(width: size, height: size) }
}

/// The bug the chick pounces on in `peck`: the family's bug icon in the issue kind's colour (MascotArt calls this).
func mascotDrawBug(_ ctx: CGContext, _ rect: CGRect, dark: Bool) {
    guard let (l, d) = BrandColor.Kind.palette["issue"] else { return }
    BlurtIcon.bug.draw(in: ctx, rect: rect, color: BrandColor.srgb(dark ? d : l).cgColor, flipped: true, weight: 1.6)
}

// MARK: - 4A line glyph motion (procedural; the glyph is one vector, so no frames)

enum GlyphMotion {
    /// A gentle head tilt, repeating (listening): rotates about the glyph's foot.
    static func tilt(_ layer: CALayer) {
        guard !reduceMotion else { return }
        let a = CAKeyframeAnimation(keyPath: "transform.rotation.z")
        a.values = [0, 0.2, 0.2, 0]
        a.keyTimes = [0, 0.35, 0.65, 1]
        a.duration = 1.4
        a.repeatCount = .infinity
        a.timingFunctions = Array(repeating: CAMediaTimingFunction(name: .easeInEaseOut), count: 3)
        layer.add(a, forKey: "blurt.tilt")
    }

    /// One small hop with squash and stretch (done).
    static func hop(_ layer: CALayer, height: CGFloat? = nil) {
        guard !reduceMotion else { return }
        let h = height ?? layer.bounds.height * 0.28
        let y = CAKeyframeAnimation(keyPath: "transform.translation.y")
        y.values = [0, 0, h, 0, 0]
        let sx = CAKeyframeAnimation(keyPath: "transform.scale.x")
        sx.values = [1, 1.12, 0.94, 1.08, 1]
        let sy = CAKeyframeAnimation(keyPath: "transform.scale.y")
        sy.values = [1, 0.86, 1.08, 0.92, 1]
        let g = CAAnimationGroup()
        for a in [y, sx, sy] { a.keyTimes = [0, 0.18, 0.45, 0.72, 1] }
        g.animations = [y, sx, sy]
        g.duration = 0.62
        g.timingFunction = CAMediaTimingFunction(controlPoints: 0.3, 0.7, 0.4, 1)
        layer.add(g, forKey: "blurt.hop")
    }

    static func stop(_ layer: CALayer) {
        layer.removeAnimation(forKey: "blurt.tilt")
        layer.removeAnimation(forKey: "blurt.hop")
    }

    /// For places that can only take an image (the menu-bar button): the glyph drawn tilted by `angle` (radians,
    /// positive = counter-clockwise, so a right-facing head lifts its beak) about `pivot` (unit coordinates of the
    /// image, y up from the bottom), and hopping: lifted by `lift` (fraction of its size) and squashed by `squash`
    /// about its foot. A template image.
    static func image(_ icon: BlurtIcon, size: CGFloat, angle: CGFloat = 0, pivot: CGPoint = CGPoint(x: 0.5, y: 0.1),
                      lift: CGFloat = 0, squash: CGFloat = 0) -> NSImage {
        image(size: size, angle: angle, pivot: pivot, lift: lift, squash: squash, template: true) { ctx, r in
            icon.draw(in: ctx, rect: r, color: NSColor.black.cgColor)
        }
    }

    /// The same motion for any drawing (the menu-bar chick, layer by layer): `draw` paints the still picture into `rect` of a
    /// y-up context; `template` = the result tints like a template image.
    static func image(size: CGFloat, angle: CGFloat = 0, pivot: CGPoint = CGPoint(x: 0.5, y: 0.1), lift: CGFloat = 0,
                      squash: CGFloat = 0, template: Bool, draw: @escaping (CGContext, CGRect) -> Void) -> NSImage {
        let img = NSImage(size: NSSize(width: size, height: size), flipped: false) { r in
            guard let ctx = NSGraphicsContext.current?.cgContext else { return false }
            let foot = r.minY + r.height * 0.1
            ctx.translateBy(x: r.midX, y: foot + r.height * lift)
            ctx.scaleBy(x: 1 + squash, y: 1 - squash)
            ctx.translateBy(x: -r.midX, y: -foot)
            let p = CGPoint(x: r.minX + r.width * pivot.x, y: r.minY + r.height * pivot.y)
            ctx.translateBy(x: p.x, y: p.y)
            ctx.rotate(by: angle)
            ctx.translateBy(x: -p.x, y: -p.y)
            draw(ctx, r)
            return true
        }
        img.isTemplate = template
        return img
    }
}
